181	        break;
182	      }
183	      // fallthrough
184	    }
185	    case PREVIEW_GEMINI_MODEL:
186	    case PREVIEW_GEMINI_MODEL_AUTO: {
187	      if (useGemini3_1) {
188	        resolved = useCustomToolModel
189	          ? PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL
190	          : PREVIEW_GEMINI_3_1_MODEL;
191	      } else {
192	        resolved = PREVIEW_GEMINI_MODEL;
193	      }
194	      break;
195	    }
196	    case DEFAULT_GEMINI_MODEL_AUTO: {
197	      resolved = DEFAULT_GEMINI_MODEL;
198	      break;
199	    }
200	    case GEMINI_MODEL_ALIAS_FLASH: {
201	      resolved = useGemini3_5Flash
202	        ? DEFAULT_GEMINI_3_5_FLASH_MODEL
203	        : PREVIEW_GEMINI_FLASH_MODEL;
204	      break;
205	    }
