273	  // Resolves a model ID to a concrete model ID based on the provided context.
274	  resolveModelId(
275	    requestedName: string,
276	    context: ResolutionContext = {},
277	  ): string {
278	    const resolution = this.config.modelIdResolutions?.[requestedName];
279	    if (!resolution) {
280	      return requestedName;
281	    }
282	
283	    for (const ctx of resolution.contexts ?? []) {
284	      if (this.matches(ctx.condition, context)) {
285	        return ctx.target;
286	      }
287	    }
288	
289	    return resolution.default;
290	  }
291	
292	  // Resolves a classifier model ID to a concrete model ID based on the provided context.
293	  resolveClassifierModelId(
294	    tier: string,
295	    requestedModel: string,
296	    context: ResolutionContext = {},
297	  ): string {
298	    const resolution = this.config.classifierIdResolutions?.[tier];
299	    const fullContext: ResolutionContext = { ...context, requestedModel };
300	
301	    if (!resolution) {
302	      // Fallback to regular model resolution if no classifier-specific rule exists
303	      return this.resolveModelId(tier, fullContext);
304	    }
305	
306	    for (const ctx of resolution.contexts ?? []) {
307	      if (this.matches(ctx.condition, fullContext)) {
308	        return ctx.target;
309	      }
310	    }
311	
312	    return resolution.default;
313	  }
