319	  /**
320	   * Fetches a chain template and resolves all model IDs within it
321	   * based on the provided context.
322	   */
323	  resolveChain(
324	    chainName: string,
325	    context: ResolutionContext = {},
326	  ): ModelPolicy[] | undefined {
327	    const template = this.config.modelChains?.[chainName];
328	    if (!template) {
329	      return undefined;
330	    }
331	    // Map through the template and resolve each model ID
