18	export class FallbackStrategy implements RoutingStrategy {
19	  readonly name = 'fallback';
20	
21	  async route(
22	    context: RoutingContext,
23	    config: Config,
24	    _baseLlmClient: BaseLlmClient,
25	    _localLiteRtLmClient: LocalLiteRtLmClient,
26	  ): Promise<RoutingDecision | null> {
27	    const requestedModel = context.requestedModel ?? config.getModel();
28	    const resolvedModel = resolveModel(
29	      requestedModel,
30	      config.getGemini31LaunchedSync?.() ?? false,
31	      false,
32	      config.getHasAccessToPreviewModel?.() ?? true,
33	      config,
34	      config.hasGemini35FlashGAAccess?.() ?? false,
35	    );
36	    const service = config.getModelAvailabilityService();
37	    const snapshot = service.snapshot(resolvedModel);
38	
39	    if (snapshot.available) {
40	      return null;
41	    }
42	
43	    const selection = selectModelForAvailability(config, requestedModel);
44	
45	    if (
46	      selection?.selectedModel &&
47	      selection.selectedModel !== requestedModel
48	    ) {
49	      return {
50	        model: selection.selectedModel,
51	        metadata: {
52	          source: this.name,
53	          latencyMs: 0,
54	          reasoning: `Model ${requestedModel} is unavailable (${snapshot.reason}). Using fallback: ${selection.selectedModel}`,
55	        },
56	      };
57	    }
58	
59	    return null;
60	  }
61	}
